import React, { useEffect, useRef } from 'react';
import './Cursor.css';

export default function Cursor() {
  const dotRef     = useRef(null);
  const ringRef    = useRef(null);
  const rafRef     = useRef(null);
  const posRef     = useRef({ x: -300, y: -300 });
  const ringPos    = useRef({ x: -300, y: -300 });
  const visibleRef = useRef(false);
  const hoverRef   = useRef(false);

  useEffect(() => {
    if (window.matchMedia('(hover: none)').matches) return;

    const dot  = dotRef.current;
    const ring = ringRef.current;
    if (!dot || !ring) return;

    /* Show on first move */
    function onMouseMove(e) {
      posRef.current = { x: e.clientX, y: e.clientY };
      if (!visibleRef.current) {
        visibleRef.current = true;
        dot.style.opacity  = '1';
        ring.style.opacity = '1';
      }
    }

    function onMouseLeave() {
      dot.style.opacity  = '0';
      ring.style.opacity = '0';
      visibleRef.current = false;
    }
    function onMouseEnter() {
      if (!visibleRef.current) return;
      dot.style.opacity  = '1';
      ring.style.opacity = '1';
    }

    /* Hover states */
    function onMouseOver(e) {
      const el = e.target.closest('a, button, [role="button"], input, textarea, select');
      if (el && !hoverRef.current) {
        hoverRef.current = true;
        dot.classList.add('cursor--hover');
        ring.classList.add('cursor--hover');
      }
    }
    function onMouseOut(e) {
      const el = e.target.closest('a, button, [role="button"], input, textarea, select');
      if (el && hoverRef.current) {
        hoverRef.current = false;
        dot.classList.remove('cursor--hover');
        ring.classList.remove('cursor--hover');
      }
    }

    /* RAF loop — dot instant, ring lerped */
    function lerp(a, b, t) { return a + (b - a) * t; }

    function loop() {
      const { x, y } = posRef.current;
      dot.style.transform = `translate(${x}px,${y}px)`;
      ringPos.current.x = lerp(ringPos.current.x, x, 0.1);
      ringPos.current.y = lerp(ringPos.current.y, y, 0.1);
      ring.style.transform = `translate(${ringPos.current.x}px,${ringPos.current.y}px)`;
      rafRef.current = requestAnimationFrame(loop);
    }

    rafRef.current = requestAnimationFrame(loop);
    document.documentElement.style.cursor = 'none';

    document.addEventListener('mousemove',  onMouseMove);
    document.addEventListener('mouseleave', onMouseLeave);
    document.addEventListener('mouseenter', onMouseEnter);
    document.addEventListener('mouseover',  onMouseOver);
    document.addEventListener('mouseout',   onMouseOut);

    return () => {
      document.removeEventListener('mousemove',  onMouseMove);
      document.removeEventListener('mouseleave', onMouseLeave);
      document.removeEventListener('mouseenter', onMouseEnter);
      document.removeEventListener('mouseover',  onMouseOver);
      document.removeEventListener('mouseout',   onMouseOut);
      if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = null; }
      document.documentElement.style.cursor = '';
    };
  }, []);

  return (
    <div className="custom-cursor" aria-hidden="true" role="presentation"
      aria-roledescription="decorative cursor">
      <div ref={dotRef}  className="cursor__dot"  />
      <div ref={ringRef} className="cursor__ring" />
    </div>
  );
}
