import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLang } from '../hooks/useLang';
import './ScrollToTop.css';

const SHOW_THRESHOLD = 380;

export default function ScrollToTop() {
  const { t }                      = useLang();
  const [visible, setVisible]      = useState(false);
  const prevVisibleRef             = useRef(false);

  /* Only setState when value actually changes — no needless renders */
  useEffect(() => {
    function onScroll() {
      const shouldShow = window.scrollY > SHOW_THRESHOLD;
      if (shouldShow !== prevVisibleRef.current) {
        prevVisibleRef.current = shouldShow;
        setVisible(shouldShow);
      }
    }
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const scrollToTop = useCallback(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <button
      className={`scroll-top${visible ? ' scroll-top--visible' : ''}`}
      onClick={scrollToTop}
      aria-label={t('aria_scroll_top')}
      aria-hidden={!visible}
      tabIndex={visible ? 0 : -1}
    >
      <svg className="scroll-top__icon" viewBox="0 0 16 16" fill="none" aria-hidden="true">
        <path d="M8 12V4M4 8l4-4 4 4" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
      </svg>
      <span className="scroll-top__ring" aria-hidden="true" />
    </button>
  );
}
